WITH scored AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY device ORDER BY started_at DESC, id) AS row_seq, LAST_VALUE(browser, TRUE) OVER (PARTITION BY customer_id ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_browser, FIRST_VALUE(browser) IGNORE NULLS OVER (ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_browser FROM sessions) SELECT browser, CASE WHEN row_seq >= 8 THEN 'LARGE' ELSE 'SMALL' END AS row_seq_tier, DATE_TRUNC('MONTH', started_at) AS activity_month, COUNT_IF(country = 'DE') AS de_events, (UNIX_TIMESTAMP(MAX(started_at)) - UNIX_TIMESTAMP(MIN(started_at))) / 60 AS duration_min, AVG(row_seq) FILTER (WHERE country = 'US') AS us_avg_row_seq, APPROX_PERCENTILE(row_seq, ARRAY(0.25, 0.5, 0.75)) AS row_seq_quartiles FROM scored GROUP BY browser, CASE WHEN row_seq >= 8 THEN 'LARGE' ELSE 'SMALL' END, DATE_TRUNC('MONTH', started_at);
